import {sites} from './data.js';
const $=s=>document.querySelector(s),svgNS='http://www.w3.org/2000/svg';
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
const storeKey='architecture-atlas-visited-v1';let visited=new Set();try{visited=new Set(JSON.parse(localStorage.getItem(storeKey)||'[]').filter(id=>sites.some(s=>s.id===id)))}catch{}
let current=-1,busy=false,projection=null,mapReady=false,view=null,mapZoom={x:0,y:0,k:1},lastFocus=null;
const timeline=$('#timeline-items'),catalog=$('#catalog'),world=$('#map-world');
function node(tag,attrs={},text){const n=document.createElementNS(svgNS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function announce(t){$('#announcer').textContent=t}
function syncVisits(){const n=String(visited.size).padStart(2,'0');$('#visited').textContent=`已探索 ${n} / 12`;document.querySelectorAll('[data-site]').forEach(e=>e.classList.toggle('visited',visited.has(e.dataset.site)));try{localStorage.setItem(storeKey,JSON.stringify([...visited]))}catch{}}
function siteButton(s,i){const b=document.createElement('button');b.className='timeline-item';b.dataset.site=s.id;b.setAttribute('aria-label',`${s.year}年，${s.name}，${s.place}`);b.innerHTML=`<span class="date">${s.year}</span><span class="label">${s.short}</span>`;b.onclick=()=>enter(i);return b}
sites.forEach((s,i)=>timeline.append(siteButton(s,i)));
function renderCatalog(query=''){const list=$('#catalog-list');list.replaceChildren();let count=0;sites.forEach((s,i)=>{if(!`${s.name}${s.place}${s.year}`.includes(query.trim()))return;count++;const b=document.createElement('button');b.className='catalog-item';b.dataset.site=s.id;b.innerHTML=`<span class="date">${s.year}</span><span><strong>${s.name}</strong><small>${s.place} · ${s.type}</small></span><em>${visited.has(s.id)?'✓':'↗'}</em>`;b.onclick=()=>{catalog.close();enter(i)};list.append(b)});if(!count){const p=document.createElement('p');p.className='empty';p.textContent='没有找到这处建筑，试试城市或省份。';list.append(p)}}
$('#directory').onclick=()=>{renderCatalog();$('#search').value='';catalog.showModal();$('#search').focus()};$('#search').oninput=e=>renderCatalog(e.target.value);$('#close-catalog').onclick=()=>catalog.close();catalog.addEventListener('click',e=>{if(e.target===catalog){let r=catalog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)catalog.close()}});
$('#start').onclick=()=>enter(sites.findIndex(s=>!visited.has(s.id))===-1?0:sites.findIndex(s=>!visited.has(s.id)));
$('#back').onclick=leave;$('.brand').onclick=e=>{e.preventDefault();if(current>=0)leave()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!catalog.open&&current>=0){e.preventDefault();leave()}});
$('#next').onclick=()=>enter((current+1)%sites.length);
syncVisits();

// Albers equal-area projection. GeoJSON is kept intact; southern islands are also
// shown in an inset so the main map remains legible on classroom screens.
function rawProject([lon,lat]){const r=Math.PI/180,p1=25*r,p2=47*r,n=(Math.sin(p1)+Math.sin(p2))/2,C=Math.cos(p1)**2+2*n*Math.sin(p1),rho=Math.sqrt(C-2*n*Math.sin(lat*r))/n,rho0=Math.sqrt(C-2*n*Math.sin(38*r))/n,t=n*(lon-105)*r;return [rho*Math.sin(t),rho0-rho*Math.cos(t)]}
function polygons(f){return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[]}
function pathOf(polys,project){return polys.map(poly=>poly.map(ring=>ring.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(2)).join(',')}`).join('')+'Z').join('')).join('')}
async function loadMap(){try{const res=await fetch('./assets/china.json');if(!res.ok)throw Error('map');const geo=await res.json();const points=geo.features.flatMap(f=>polygons(f).flat(2)).filter(p=>p[1]>=17.7).map(rawProject);const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const sc=Math.min(970/(maxX-minX),640/(maxY-minY));projection=p=>{let [x,y]=rawProject(p);return [72+(x-minX)*sc,63+(maxY-y)*sc]};
 const land=node('g',{filter:'url(#mapShadow)'});world.append(land);for(const f of geo.features){const polys=polygons(f).filter(poly=>poly[0].some(p=>p[1]>=17.7));if(!polys.length)continue;const path=node('path',{d:pathOf(polys,projection),class:'province','fill-rule':'evenodd'});path.append(node('title',{},f.properties.name||'南海诸岛'));land.append(path)}
 const labels=node('g');world.append(labels);for(const f of geo.features){const name=f.properties.name,center=f.properties.centroid||f.properties.center;if(!center||!name||['北京市','天津市','上海市','香港特别行政区','澳门特别行政区','重庆市'].includes(name))continue;let [x,y]=projection(center);labels.append(node('text',{x,y,class:'province-label','text-anchor':'middle'},name.replace(/省|壮族自治区|回族自治区|维吾尔自治区|自治区/g,'')))}
 const inset=node('g',{transform:'translate(930 565)'});inset.append(node('rect',{x:0,y:0,width:110,height:160,rx:1,fill:'#e6e8d9',stroke:'#a5b09d','stroke-width':.7}));for(const f of geo.features){const polys=polygons(f).filter(poly=>poly[0].some(p=>p[1]<18&&p[0]>106));if(polys.length)inset.append(node('path',{d:pathOf(polys,p=>[12+(p[0]-106)*6.8,130-(p[1]-3)*7]),fill:'#9cae98',stroke:'#738a74','stroke-width':.6}))}inset.append(node('text',{x:55,y:149,'text-anchor':'middle',class:'inset-label'},'南海诸岛'));world.append(inset);
 const layer=node('g',{id:'markers'});world.append(layer);sites.forEach((s,i)=>{const [x,y]=projection(s.coord),[dx,dy]=s.offset;const marker=node('g',{class:'marker','data-site':s.id,tabindex:0,role:'button','aria-label':`${s.name}，${s.place}，点击进入`});marker.append(node('line',{x1:x,y1:y,x2:x+dx,y2:y+dy}));marker.append(node('circle',{cx:x,cy:y,r:3.2,fill:'#a84030'}));const group=node('g',{transform:`translate(${x+dx} ${y+dy})`});group.append(node('circle',{r:20,class:'hit'}));group.append(node('circle',{r:9,class:'halo'}));group.append(node('circle',{r:4.8,class:'pin'}));const right=dx>=0;group.append(node('text',{x:right?15:-15,y:4,'text-anchor':right?'start':'end'},s.short));marker.append(group);marker.addEventListener('click',()=>enter(i));marker.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enter(i)}});layer.append(marker)});mapReady=true;$('#map-loading').hidden=true;syncVisits();const initial=sites.findIndex(s=>`#${s.id}`===location.hash);if(initial>=0)enter(initial);
 }catch(e){$('#map-loading').innerHTML='地图暂时未能展开。<button id="retry-map">重试</button><br><small>也可以通过下方时间线进入建筑。</small>';$('#retry-map').onclick=()=>{world.replaceChildren();loadMap()};console.error('地图加载失败',e)}}
loadMap();
const easing=t=>t<.5?4*t*t*t:1-(-2*t+2)**3/2;
function tween(ms,draw){if(reduceMotion.matches){draw(1);return Promise.resolve()}return new Promise(resolve=>{let start;function frame(now){start??=now;let t=Math.min(1,(now-start)/ms);draw(easing(t));if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})}
async function zoomMap(target,ms){const from={...mapZoom};await tween(ms,t=>{mapZoom={x:from.x+(target.x-from.x)*t,y:from.y+(target.y-from.y)*t,k:from.k+(target.k-from.k)*t};world.setAttribute('transform',`translate(${mapZoom.x} ${mapZoom.y}) scale(${mapZoom.k})`)})}
function setBusy(value){busy=value;$('#back').disabled=value;$('#next').disabled=value;$('#start').disabled=value;$('#directory').disabled=value;document.body.classList.toggle('transitioning',value)}
async function initView(){if(view)return view;const [{default:View}]=await Promise.all([import('./scene.js?v=7')]);view=new View($('#canvas-wrap'));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view.setView(b.dataset.view));$('#rotate').onclick=()=>{const active=$('#rotate').getAttribute('aria-pressed')!=='true';$('#rotate').setAttribute('aria-pressed',String(active));view.setRotate(active)};return view}
function fill(s,i){$('#site-place').textContent=s.place;$('#site-number').textContent=`${String(i+1).padStart(2,'0')} / 12`;$('#site-name').textContent=s.name;$('#site-year').textContent=s.year;$('#site-intro').textContent=s.intro;$('#site-type').textContent=s.type;$('#site-detail').textContent=s.detail;$('#site-source').href=s.source;$('#site-source').textContent=`${s.publisher} ↗`;$('.scene-watermark').textContent=s.province;$('#next strong').textContent=sites[(i+1)%12].short;$('.info-panel').scrollTop=0;$('.info-panel details').open=false;$('#scene').scrollTop=0;$('#rotate').setAttribute('aria-pressed','false')}
async function enter(i){if(busy||i<0||i>=sites.length)return;setBusy(true);const fromMap=current<0;lastFocus=fromMap?document.activeElement:lastFocus;const s=sites[i];try{if(!fromMap){$('#scene').classList.remove('active');await tween(250,()=>{})}fill(s,i);current=i;if(!fromMap&&mapReady){const [px,py]=projection(s.coord);mapZoom={x:550-px*12,y:390-py*12,k:12};world.setAttribute('transform',`translate(${mapZoom.x} ${mapZoom.y}) scale(12)`)}const scene=$('#scene');if(fromMap){$('#atlas').setAttribute('inert','');$('.timeline').setAttribute('inert','');if(mapReady){const [x,y]=projection(s.coord);const k=12;await zoomMap({x:550-x*k,y:390-y*k,k},950)}}scene.hidden=false;await new Promise(r=>requestAnimationFrame(r));scene.classList.add('active');$('#scene-loading').hidden=false;try{const v=await initView();await v.show(s.model,reduceMotion.matches);$('#scene-loading').hidden=true}catch(err){$('#scene-loading').hidden=true;let p=$('#webgl-error');if(!p){p=document.createElement('div');p.id='webgl-error';p.className='webgl-error';$('#canvas-wrap').append(p)}p.textContent='当前浏览器暂不支持三维显示。建筑介绍仍可阅读，请使用支持 WebGL 的浏览器查看模型。';console.error('建筑场景未能显示',err)}visited.add(s.id);syncVisits();history.replaceState(null,'',`#${s.id}`);announce(`已进入${s.name}。可以拖动旋转建筑，也可以选择继续探索返回地图。`);document.title=`${s.short} · 毛泽东思想——中国建筑`;
 }finally{setBusy(false);$('#back').focus({preventScroll:true})}}
async function leave(){if(busy||current<0)return;setBusy(true);try{if(view)await view.depart(reduceMotion.matches);$('#scene').classList.remove('active');await tween(450,()=>{});$('#scene').hidden=true;view?.pause();await zoomMap({x:0,y:0,k:1},900);current=-1;$('#atlas').removeAttribute('inert');$('.timeline').removeAttribute('inert');history.replaceState(null,'',location.pathname+location.search);document.title='毛泽东思想——中国建筑';announce('已返回中国地图，继续探索下一处建筑。');if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true})}finally{setBusy(false)}}
window.addEventListener('hashchange',()=>{const i=sites.findIndex(s=>`#${s.id}`===location.hash);if(i>=0)enter(i);else if(current>=0)leave()});

$('#canvas-wrap').addEventListener('viewerror',()=>{let p=$('#webgl-error');if(!p){p=document.createElement('div');p.id='webgl-error';p.className='webgl-error';$('#canvas-wrap').append(p)}p.textContent='三维显示已暂停。请刷新页面重新加载；建筑介绍仍可阅读。';announce('三维显示已暂停，请刷新页面重试。')});
